  let x = 10;
  function inner() { console.log(x); } // captures the variable x
  x = 20;                              // mutated before inner runs
  return inner;
}
outer()(); // 20 — closures see the latest value, not a snapshot
```

exec-callstack-001.example:
```js
function first() { second(); console.log('first done'); }
function second() { third(); console.log('second done'); }
function third() { console.log('third done'); }
first();
// push order: first → second → third
// logs (as each returns/pops): third done, second done, first done
```

exec-callstack-002.example:
```js
function c() { console.log('c runs'); return 1; }
function b() { const r = c(); console.log('b resumes'); return r; }
function a() { const r = b(); console.log('a resumes'); return r; }
console.log('result:', a());
// c runs → b resumes → a resumes → result: 1
// push a,b,c then pop c,b,a (LIFO)
```

exec-callstack-mcq-003.example:
```js
function recurse() { return recurse(); } // never returns — frames pile up
try {
  recurse();
} catch (e) {
  console.log(e.constructor.name); // RangeError (in V8/Node/Chrome)
  console.log(e.message);          // Maximum call stack size exceeded
}
```

