exec-eventloop-004.example:
```js
// BLOCKS the UI — synchronous, never yields:
// for (let i = 0; i < 5e9; i++) {}

// Non-blocking: chunk the work and yield to the event loop
function chunked(total, perTick, done, i = 0) {
  const end = Math.min(i + perTick, total);
  for (; i < end; i++) { /* work */ }
  if (i < total) setTimeout(() => chunked(total, perTick, done, i), 0);
  else done();
}
chunked(1e6, 1e5, () => console.log('done without freezing'));
```

