this-cab-001.example:
```js
function intro(greeting, mark) { return `${greeting}, ${this.name}${mark}`; }
const user = { name: 'Sam' };
console.log(intro.call(user, 'Hi', '!'));    // 'Hi, Sam!' — args individually
console.log(intro.apply(user, ['Hey', '?'])); // 'Hey, Sam?' — args as array
const bound = intro.bind(user, 'Yo');
console.log(bound('.'));                      // 'Yo, Sam.' — this preset, returns fn
```

