proto-class-001.example:
```js
class Person {
  constructor(name) { this.name = name; }
  hi() { return 'hi ' + this.name; }
}
const p = new Person('Lee');
console.log(typeof Person);                                  // 'function'
console.log(Object.getPrototypeOf(p) === Person.prototype);  // true
console.log(p.hi === Person.prototype.hi);                   // true — shared, not copied
```

proto-class-002.example:
```js
const proto = { describe() { return `id ${this.id}`; } };
const a = Object.create(proto); // no constructor runs
a.id = 1;
console.log(a.describe()); // 'id 1'

function Thing(id) { this.id = id; } // constructor initializes state
Thing.prototype.describe = function () { return `id ${this.id}`; };
const b = new Thing(2);
console.log(b.describe()); // 'id 2'
```

proto-class-mcq-003.example:
```js
class Animal { speak() { return 'generic'; } }
class Dog extends Animal { speak() { return 'woof'; } }
const d = new Dog();
console.log(d.speak());                                            // 'woof'
console.log(Object.getPrototypeOf(d) === Dog.prototype);          // true
console.log(Object.getPrototypeOf(Dog.prototype) === Animal.prototype); // true
```
